window.IFR_DATA = {"domains": {"1": "Regulations and Equipment", "2": "Weather", "3": "Planning and ATC", "4": "Instruments and Navigation", "5": "En Route, Holding, and Approaches", "6": "Emergencies and Human Factors"}, "tests": [{"id": 3, "name": "Practice Test 3", "questions": [{"n": 1, "stem": "Unless otherwise published, what is the maximum holding airspeed at 16,000 feet MSL?", "options": ["200 KIAS", "210 KIAS", "230 KIAS", "265 KIAS"], "domain": 5, "answer": 3, "rationale": "Maximum holding speeds are 200 KIAS through 6,000 feet MSL, 230 KIAS from 6,001 through 14,000 feet MSL, and 265 KIAS above 14,000 feet MSL. At 16,000 feet the limit is 265 KIAS unless a different speed is published."}, {"n": 2, "stem": "A pilot flying a STAR receives the clearance \"descend via\" that arrival. What does this authorize?", "options": ["An immediate descent to the lowest altitude on the STAR", "Descent at pilot's discretion while meeting the published altitude and speed restrictions on the procedure", "Descent only after the pilot reports each fix", "Descent to the MEA, ignoring the published restrictions"], "domain": 3, "answer": 1, "rationale": "A \"descend via\" clearance authorizes descent at pilot's discretion while complying with the altitude and speed restrictions published on the procedure. It does not permit an immediate descent to the lowest altitude (A) or ignoring the restrictions (D)."}, {"n": 3, "stem": "A pilot flies at an indicated altitude of 6,000 feet with the correct local altimeter setting, but the air is much colder than standard. Compared with the indicated altitude, the true altitude is", "options": ["Lower", "Higher", "The same, because the altimeter setting corrects for temperature", "Higher at night and lower during the day"], "domain": 4, "answer": 0, "rationale": "In air colder than standard, the pressure levels are closer together, so the airplane is lower than the altimeter shows: \"high to low, look out below\" applies to temperature as well as pressure. The altimeter setting corrects for pressure, not temperature (C). This is why cold temperature corrections matter near terrain."}, {"n": 4, "stem": "On Monday morning, a pilot calls Flight Service to plan an IFR flight departing Tuesday afternoon. Which briefing type fits best?", "options": ["Abbreviated briefing", "Standard briefing", "Outlook briefing", "Inflight briefing"], "domain": 3, "answer": 2, "rationale": "An outlook briefing is for a departure 6 or more hours away and supports early planning. The pilot should still get a standard briefing (B) closer to departure. An abbreviated briefing (A) updates earlier information, and an inflight briefing (D) is obtained while airborne."}, {"n": 5, "stem": "An IFR route passes through an active military operations area (MOA). How will ATC normally handle the flight?", "options": ["Clear it through the MOA if IFR separation can be provided, or reroute or restrict it if not", "Clear it through the MOA without restriction, because MOAs never affect IFR flights", "Require the pilot to cancel IFR and continue VFR through the MOA", "Require the pilot to obtain permission from the military controlling agency"], "domain": 3, "answer": 0, "rationale": "When a MOA is active, nonparticipating IFR traffic may be cleared through it if ATC can provide IFR separation. Otherwise ATC will reroute or restrict the flight. The pilot does not cancel IFR (C) or contact the military agency for permission (D)."}, {"n": 6, "stem": "An automated weather station reports CLR in the sky condition group. What does this mean?", "options": ["No clouds were detected at or below 12,000 feet", "The sky is completely free of clouds at every altitude", "No clouds are present below 18,000 feet MSL", "Clouds are present, but the sensor cannot measure their height"], "domain": 2, "answer": 0, "rationale": "Automated stations report CLR when no clouds are detected at or below 12,000 feet, the practical limit of the ceilometer. Clouds may exist above that height, so CLR does not mean a cloudless sky (B). A human observer reports SKC for a clear sky."}, {"n": 7, "stem": "In icing conditions, a pilot extends the flaps on approach, and the airplane suddenly pitches nose-down while the elevator forces feel light. What is generally the recommended response?", "options": ["Push forward on the yoke and add full power, as for a wing stall", "Extend the flaps further to increase lift", "Retract the flaps to the previous setting and pull back on the yoke, following the flight manual", "Lower the nose to increase airspeed until the buffet stops"], "domain": 2, "answer": 2, "rationale": "These are signs of an ice-contaminated tailplane stall. Recovery is the opposite of a wing stall: return the flaps to the previous setting and apply nose-up elevator, adjusting power as the flight manual directs. Pushing forward (A), adding flaps (B), or gaining airspeed (D) increases the tailplane's angle of attack problem and can make it worse."}, {"n": 8, "stem": "An RNAV (GPS) approach has LP minimums. Which statement is correct?", "options": ["LP provides vertical guidance and a decision altitude, like LPV", "LP is a lateral-only approach flown to an MDA, with localizer-like lateral precision", "LP minimums may be flown with any non-WAAS GPS", "LP approaches always allow descent to 200 feet above the touchdown zone"], "domain": 5, "answer": 1, "rationale": "LP (localizer performance) uses WAAS for precise lateral guidance, similar to a localizer, but has no approved vertical guidance, so it is flown to an MDA. It requires a WAAS receiver approved for LP (C). LPV, not LP, provides a decision altitude (A), and LP minimums are typically higher than 200 feet (D)."}, {"n": 9, "stem": "An airplane is on a magnetic heading of 040°, and the ADF shows a relative bearing of 330°. What is the magnetic bearing to the station?", "options": ["290°", "010°", "070°", "190°"], "domain": 4, "answer": 1, "rationale": "Magnetic heading plus relative bearing equals magnetic bearing to the station: 040 + 330 = 370, and 370 − 360 = 010°. The reciprocal of 010° is 190° (D), which is the bearing from the station."}, {"n": 10, "stem": "Over the 48 contiguous states, outside Class A, B, and C airspace, where is ADS-B Out generally required?", "options": ["At and above 3,000 feet AGL everywhere", "At and above 10,000 feet MSL, excluding airspace at and below 2,500 feet AGL", "Only at and above 18,000 feet MSL", "Only within 30 NM of a Class B primary airport"], "domain": 1, "answer": 1, "rationale": "Section 91.225 requires ADS-B Out in Class E airspace at and above 10,000 feet MSL over the 48 contiguous states and the District of Columbia, excluding airspace at and below 2,500 feet AGL. The 30 NM Mode C veil (D) is another area where it is required, but not the only one. 18,000 feet (C) is the base of Class A, and A is not a rule."}, {"n": 11, "stem": "How does the vertical speed indicator respond when the pitch attitude changes?", "options": ["It shows the correct rate immediately but no trend", "It shows the trend at once, but the stabilized rate only after a lag of several seconds", "It reads zero until the climb or descent has been steady for a minute", "It shows a reversed indication for about 30 seconds"], "domain": 4, "answer": 1, "rationale": "The VSI shows a trend almost immediately, but it takes about 6 to 9 seconds to show an accurate, stabilized rate because of the calibrated leak. That lag is why pilots set pitch with the attitude indicator and use the VSI to confirm the rate."}, {"n": 12, "stem": "ATC clears a pilot at 9,000 feet to \"descend at pilot's discretion, maintain 5,000.\" Which statement is correct?", "options": ["The pilot must begin the descent immediately at 500 feet per minute", "The pilot may start when desired, descend at any rate, and level off at intermediate altitudes, but may not return to an altitude once it has been vacated", "The pilot may descend to 5,000 feet and then climb back to 9,000 feet if desired", "The pilot must report reaching each 1,000-foot interval"], "domain": 3, "answer": 1, "rationale": "\"At pilot's discretion\" lets the pilot begin the descent whenever desired, use any rate, and level off temporarily at an intermediate altitude. Once the pilot vacates an altitude, however, the pilot may not return to it (C). Nothing requires an immediate start (A) or reports at every 1,000 feet (D), although leaving an assigned altitude is still reported."}, {"n": 13, "stem": "The clock required for IFR flight under 91.205(d) must display", "options": ["Local time and UTC at the same time", "Hours and minutes only, in digital form", "Elapsed time with a start-stop function", "Hours, minutes, and seconds, with a sweep-second pointer or a digital presentation"], "domain": 1, "answer": 3, "rationale": "Section 91.205(d)(6) requires a clock displaying hours, minutes, and seconds with a sweep-second pointer or digital presentation. Seconds matter for timed approaches and holding legs. The rule does not require two time zones (A) or a timer function (C), and a display without seconds (B) does not meet it."}, {"n": 14, "stem": "An abrupt change from a climb to straight-and-level flight in clouds can create a feeling of tumbling backward. What is this illusion, and what is the risk?", "options": ["Coriolis illusion; the pilot may roll the airplane", "Elevator illusion; the pilot may pull the nose up", "The leans; the pilot may bank in the wrong direction", "Inversion illusion; the pilot may push the nose down abruptly"], "domain": 6, "answer": 3, "rationale": "The inversion illusion follows an abrupt change from climb to straight-and-level flight and produces a feeling of tumbling backward. The pilot may push the nose down abruptly, which can intensify the illusion. Trusting the attitude indicator is the defense."}, {"n": 15, "stem": "According to the AIM, how far ahead of the estimated departure time should a pilot normally file an IFR flight plan?", "options": ["At least 30 minutes", "At least 2 hours", "At least 1 hour", "At least 10 minutes"], "domain": 3, "answer": 0, "rationale": "The AIM recommends filing an IFR flight plan at least 30 minutes before the estimated time of departure to avoid delay in receiving the departure clearance. Filing earlier is fine, but 30 minutes is the guidance."}, {"n": 16, "stem": "An airplane uses VOR equipment as its required navigation equipment. At or above what level must it also have approved DME or a suitable RNAV system?", "options": ["12,500 feet MSL", "18,000 feet MSL", "FL240", "FL290"], "domain": 1, "answer": 2, "rationale": "Section 91.205(e) requires approved DME or a suitable RNAV system at and above FL240 when VOR navigation equipment is required. 18,000 feet MSL (B) is the base of Class A airspace, not this requirement. 12,500 feet (A) is associated with crew oxygen rules, and FL290 (D) is associated with RVSM airspace."}, {"n": 17, "stem": "A pilot needs to tell ATC about an urgent problem that is not yet a distress situation. Which spoken signal is used?", "options": ["MAYDAY, MAYDAY, MAYDAY", "SECURITE, SECURITE, SECURITE", "PAN-PAN, PAN-PAN, PAN-PAN", "EMERGENCY, EMERGENCY, EMERGENCY"], "domain": 6, "answer": 2, "rationale": "PAN-PAN, spoken three times, signals an urgency condition. MAYDAY (A), spoken three times, signals distress, a condition of being threatened by serious or imminent danger. A pilot who is unsure should not hesitate to declare an emergency and ask for help."}, {"n": 18, "stem": "Where is a pilot most likely to find the published preferred IFR routes between major terminal areas?", "options": ["The approach chart for the destination", "The METAR remarks for the departure airport", "The en route chart legend", "The Chart Supplement"], "domain": 3, "answer": 3, "rationale": "Preferred IFR routes are listed in the Chart Supplement (and in the FAA's online preferred routes database). Filing a preferred route can reduce rerouting. Approach charts (A), METARs (B), and chart legends (C) do not list them."}, {"n": 19, "stem": "A TAF contains WS015/30045KT. What does this mean?", "options": ["Surface wind 300° at 15 knots, gusting to 45 knots", "Low-level wind shear at 1,500 feet AGL, with the wind at that height from 300° at 45 knots", "Wind shear reported by a pilot at 15,000 feet MSL", "A wind shift to 300° at 45 knots expected at 1500Z"], "domain": 2, "answer": 1, "rationale": "In a TAF, WS indicates non-convective low-level wind shear. The three digits give the height of the shear layer in hundreds of feet AGL, followed by the wind at that height. Here the layer is at 1,500 feet AGL with wind from 300° at 45 knots. It is not a surface wind (A), a pilot report (C), or a time group (D)."}, {"n": 20, "stem": "Which product replaced the textual area forecast (FA) for the contiguous United States?", "options": ["The Center Weather Advisory", "The convective outlook", "The Graphical Forecasts for Aviation (GFA)", "The low-level significant weather prognostic chart"], "domain": 2, "answer": 2, "rationale": "The GFA replaced the area forecast for the contiguous United States in 2017. It presents observations and forecasts of clouds, ceilings, visibility, precipitation, icing, turbulence, and more on one web page. CWAs (A), convective outlooks (B), and prog charts (D) are separate products that remain in use."}, {"n": 21, "stem": "A METAR includes the remark TSB32. What does it mean?", "options": ["A thunderstorm is 32 miles away", "Thunderstorm tops are at 32,000 feet", "A thunderstorm began at 32 minutes past the hour", "A thunderstorm ended 32 minutes ago"], "domain": 2, "answer": 2, "rationale": "In METAR remarks, B means began and E means ended, followed by the time in minutes past the hour (or hours and minutes). TSB32 means a thunderstorm began at 32 minutes past the hour. An ending time would use E (D), and the remark does not give distance (A) or tops (B)."}, {"n": 22, "stem": "An airport's approach light system is out of service. Where should the pilot look to see how this affects the published minimums?", "options": ["The chart notes and the Inoperative Components table in the Terminal Procedures Publication", "The en route chart legend", "The winds and temperatures aloft forecast", "The ATIS broadcast, which publishes the new minimums"], "domain": 5, "answer": 0, "rationale": "The outage itself is announced by NOTAM. Its effect on visibility minimums is found in the approach chart notes and the Inoperative Components table in the front of the Terminal Procedures Publication. ATIS (D) may mention the outage but does not publish revised minimums."}, {"n": 23, "stem": "The low-level significant weather prognostic chart covers which altitude range?", "options": ["Surface to 10,000 feet MSL", "Surface to FL180", "FL250 to FL630", "Surface to FL240"], "domain": 2, "answer": 3, "rationale": "The low-level significant weather chart covers the surface to FL240 and shows IFR and MVFR areas, moderate or greater turbulence, and freezing levels. FL250 to FL630 (C) is the range of the high-level significant weather chart."}, {"n": 24, "stem": "In a typical light airplane with conventional instruments, the vacuum pump fails. Which instruments are affected?", "options": ["Airspeed indicator and altimeter", "Turn coordinator and vertical speed indicator", "Magnetic compass and heading indicator", "Attitude indicator and heading indicator"], "domain": 4, "answer": 3, "rationale": "In most light airplanes, the attitude indicator and heading indicator are vacuum-driven gyros, so both will slowly fail. The turn coordinator is usually electric and keeps working, which is why it is a key partial-panel instrument. The pitot-static instruments (A) and the magnetic compass (C) do not use vacuum."}, {"n": 25, "stem": "On an RNAV (GPS) approach flown to LNAV minimums, what is the full-scale CDI deflection by the final approach fix?", "options": ["1 NM", "0.3 NM", "5 NM", "2 NM"], "domain": 4, "answer": 1, "rationale": "The CDI scales from 1 NM full scale in the terminal phase (A) to 0.3 NM full scale by the final approach fix in approach mode. Larger values (C, D) apply en route. LPV approaches use angular scaling instead."}, {"n": 26, "stem": "Unless ATC specifies otherwise, how should a pilot climb or descend to an assigned altitude?", "options": ["At 500 feet per minute for the entire climb or descent", "At the maximum rate the airplane can achieve all the way to the altitude", "At no more than 1,000 feet per minute at all times", "At an optimum rate until 1,000 feet from the assigned altitude, then between 500 and 1,500 feet per minute"], "domain": 3, "answer": 3, "rationale": "The AIM asks pilots to climb or descend at an optimum rate consistent with the airplane's performance until 1,000 feet from the assigned altitude, then at 500 to 1,500 feet per minute until reaching it. If unable to climb or descend at least 500 feet per minute, the pilot should tell ATC."}, {"n": 27, "stem": "Before an IFR flight that relies on a non-WAAS (TSO-C129) GPS, what should the pilot confirm?", "options": ["That RAIM is predicted to be available along the route and at the destination for the expected times", "That the GPS antenna has been inspected within the preceding 30 days", "That at least three satellites will be in view at departure", "That WAAS LPV service is available at the destination"], "domain": 4, "answer": 0, "rationale": "A non-WAAS GPS depends on RAIM for integrity, so the pilot must confirm that RAIM is predicted to be available for the route and times of the flight. The 30-day check (B) applies to VOR receivers. Three satellites (C) are not enough for RAIM, and a non-WAAS receiver cannot use LPV (D)."}, {"n": 28, "stem": "An RNAV (GPS) chart includes the note \"Uncompensated Baro-VNAV NA below −15°C.\" The airplane uses baro-VNAV without temperature compensation, and the temperature is −20°C. What may the pilot do?", "options": ["Fly to LNAV/VNAV minimums, adding 100 feet to the DA", "Use the baro-VNAV system to fly the LPV line instead", "Fly the approach without using LNAV/VNAV minimums, for example to LNAV minimums", "Nothing; the entire approach is not authorized"], "domain": 5, "answer": 2, "rationale": "In air colder than the charted limit, an uncompensated baro-VNAV glidepath is lower than designed, so LNAV/VNAV minimums may not be used with that system. The approach can still be flown to minimums that do not depend on baro-VNAV, such as LNAV, with any required cold temperature corrections. LPV (B) requires WAAS, not baro-VNAV."}, {"n": 29, "stem": "A pilot flies IFR off published routes in a designated mountainous area. If no other minimum altitude is prescribed, what is the minimum IFR altitude?", "options": ["2,000 feet above the highest obstacle within 4 NM of the course to be flown", "1,000 feet above the highest obstacle within 4 NM of the course to be flown", "2,000 feet above the highest obstacle within 5 statute miles of the course", "1,500 feet above the terrain directly below the airplane"], "domain": 1, "answer": 0, "rationale": "Section 91.177(a)(2) sets the minimum at 2,000 feet above the highest obstacle within a horizontal distance of 4 nautical miles from the course in designated mountainous areas. Choice B is the standard for areas that are not mountainous. Choice C uses the wrong distance and units, and D measures from the terrain directly below, which is not how the rule works."}, {"n": 30, "stem": "In clouds, a pilot in a prolonged coordinated turn begins to feel the wings are level and notices altitude decreasing. Pulling back on the yoke only tightens the turn. What is happening?", "options": ["The leans", "A graveyard spiral", "The somatogravic illusion", "The elevator illusion"], "domain": 6, "answer": 1, "rationale": "In a graveyard spiral, the inner ear stops sensing a prolonged turn, so the pilot feels level while the airplane descends in a bank. Pulling back without leveling the wings tightens the spiral. The fix is to level the wings by reference to the attitude indicator first, then correct pitch."}, {"n": 31, "stem": "G-AIRMETs are issued as a series of forecast snapshots. At what interval are the snapshots?", "options": ["Every 3 hours", "Every hour", "Every 6 hours", "Every 12 hours"], "domain": 2, "answer": 0, "rationale": "G-AIRMETs are issued every 6 hours, with snapshots at 3-hour intervals out to 12 hours. Six hours (C) is the issuance cycle, not the snapshot spacing. Conditions between two snapshots may differ, so look at the snapshots on both sides of your flight time."}, {"n": 32, "stem": "In the 3P model of risk management, what are the three steps?", "options": ["Plan, Prepare, Proceed", "Perceive, Process, Perform", "Pilot, Plane, Programming", "Predict, Prevent, Protect"], "domain": 6, "answer": 1, "rationale": "The 3P model is Perceive (identify hazards), Process (evaluate the risk they create), and Perform (act to reduce the risk), repeated throughout the flight. The PAVE checklist is the tool most often used in the Perceive step."}, {"n": 33, "stem": "Which statement about operating in Class A airspace is correct?", "options": ["VFR flight is permitted with an operating transponder and ADS-B Out", "Class A begins at 14,500 feet MSL over the contiguous states", "Operations must be conducted under IFR at an altitude assigned by ATC, unless ATC authorizes otherwise", "The altimeter is set to the nearest station's setting up to FL240"], "domain": 1, "answer": 2, "rationale": "Section 91.135 requires flight in Class A airspace under IFR at an ATC-assigned altitude unless otherwise authorized. VFR (A) is not permitted. Class A begins at 18,000 feet MSL; 14,500 feet MSL (B) is where Class E begins when no lower floor is designated. At and above 18,000 feet MSL the altimeter is set to 29.92 (D)."}, {"n": 34, "stem": "Under 14 CFR 91.173, what must be in place before a pilot operates under IFR in controlled airspace?", "options": ["A weather briefing from Flight Service and a filed flight plan", "A filed IFR flight plan and an appropriate ATC clearance", "An ATC clearance and a current instrument proficiency check", "Radar contact with ATC and a filed IFR flight plan"], "domain": 1, "answer": 1, "rationale": "Section 91.173 requires two things: an IFR flight plan that has been filed and an appropriate ATC clearance that has been received. A weather briefing (A) is good practice and part of preflight action under 91.103, but 91.173 does not name it. An IPC (C) is needed only when currency has lapsed past the grace period. Radar contact (D) is not required; IFR flights operate in nonradar airspace every day."}, {"n": 35, "stem": "Which conditions produce upslope fog?", "options": ["Clear skies and calm wind over moist ground at night", "Moist, stable air pushed up rising terrain by the wind and cooled to its dew point", "Cold air moving over a much warmer water surface", "Warm rain falling through cooler, nearly saturated air"], "domain": 2, "answer": 1, "rationale": "Upslope fog forms when wind moves moist, stable air up sloping terrain and the air cools adiabatically to its dew point. It can be thick and persistent while the wind continues. Choice A describes radiation fog, C describes steam fog, and D describes precipitation-induced fog."}, {"n": 36, "stem": "What does the compass deviation card in the cockpit correct for?", "options": ["The angle between true north and magnetic north", "The dip of the earth's magnetic field toward the poles", "Errors caused by magnetic fields within the airplane, such as electrical equipment and metal parts", "Turning errors when flying near the poles"], "domain": 4, "answer": 2, "rationale": "Deviation is compass error caused by magnetic influences inside the airplane. The deviation card shows the heading to steer to achieve a desired magnetic heading. The angle between true and magnetic north (A) is variation, and dip (B) causes turning and acceleration errors (D)."}, {"n": 37, "stem": "While tuning a VOR, a pilot hears no identifier, or hears T-E-S-T in Morse code. What should the pilot conclude?", "options": ["The VOR is working normally; the identifier is broadcast only on the hour", "The VOR may be used en route but not for approaches", "The facility is a VOT and can be used to check the receiver", "The facility may be undergoing maintenance and should not be used for navigation"], "domain": 4, "answer": 3, "rationale": "During maintenance, the identifier is removed or replaced with a T-E-S-T code, and the facility may radiate signals that look usable but are not reliable. Do not navigate with it. A VOT (C) has its own identification, a series of dots or a continuous tone."}, {"n": 38, "stem": "How is touchdown zone elevation (TDZE) defined?", "options": ["The highest elevation in the first 3,000 feet of the landing surface", "The average elevation of the entire runway", "The elevation of the runway threshold", "The highest point on any usable runway at the airport"], "domain": 5, "answer": 0, "rationale": "TDZE is the highest elevation in the first 3,000 feet of the landing surface. Straight-in minimums show height above touchdown (HAT) relative to it. The highest point on any usable runway (D) is the airport elevation, which is used for circling minimums."}, {"n": 39, "stem": "What is a maximum authorized altitude (MAA)?", "options": ["The highest altitude on a route segment at which adequate reception of navigation signals is assured", "The highest altitude ATC may assign below Class A airspace", "The highest altitude at which the airplane may fly without supplemental oxygen", "The maximum altitude for a procedure turn"], "domain": 5, "answer": 0, "rationale": "The MAA is the highest usable altitude or flight level on an airway or route segment, at which adequate reception of navigation signals is assured. Above it, signals from other stations on the same frequency may interfere. It has nothing to do with Class A (B), oxygen (C), or procedure turns (D)."}, {"n": 40, "stem": "During straight-and-level flight at a constant airspeed, which instrument is primary for pitch?", "options": ["Altimeter", "Attitude indicator", "Airspeed indicator", "Vertical speed indicator"], "domain": 4, "answer": 0, "rationale": "In the primary and supporting method, the altimeter is the primary pitch instrument in straight-and-level flight, because it directly shows whether altitude is being held. The attitude indicator (B) and VSI (D) are supporting pitch instruments, and the airspeed indicator (C) is primary for power."}, {"n": 41, "stem": "An en route chart shows a minimum crossing altitude (MCA) at an intersection. What does it require?", "options": ["Cross the intersection at or below the MCA in either direction", "Cross the intersection at the MCA only when holding there", "Cross the intersection at or above the MCA when proceeding in the direction of the higher MEA", "Begin a climb to the MCA only after passing the intersection"], "domain": 5, "answer": 2, "rationale": "An MCA is the lowest altitude at which a fix must be crossed when proceeding in the direction of a higher MEA, usually because of obstacles beyond the fix. The climb must be completed before reaching the fix, not after it (D). The MCA applies in the direction shown, and it is a minimum, not a maximum (A)."}, {"n": 42, "stem": "A pilot is cleared for an approach that uses a holding pattern in lieu of a procedure turn. The pilot wants to fly an extra circuit to lose altitude. What should the pilot do?", "options": ["Fly as many circuits as needed without telling ATC", "Skip the hold entirely, because the approach clearance covers it", "Advise ATC, ideally when receiving the approach clearance, before flying additional circuits", "Declare an emergency to obtain the extra time"], "domain": 5, "answer": 2, "rationale": "When cleared for the approach, the pilot is expected to make one circuit of a holding pattern in lieu of a procedure turn. If the pilot needs additional circuits, for example to lose excess altitude, the AIM makes it the pilot's responsibility to advise ATC upon receipt of the approach clearance. The course reversal is not optional (B) unless ATC or the procedure says so."}, {"n": 43, "stem": "While being radar vectored on an unpublished route, a pilot is cleared for an approach. What altitude must the pilot maintain?", "options": ["The MSA shown on the approach chart until the final approach fix", "The last altitude assigned by ATC until established on a segment of a published route or approach procedure, unless ATC assigns a different altitude", "The procedure turn completion altitude until the final approach fix", "Any altitude at or above the minimum vectoring altitude"], "domain": 5, "answer": 1, "rationale": "Section 91.175(i) requires a pilot on an unpublished route or being radar vectored, when cleared for an approach, to maintain the last assigned altitude until established on a segment of a published route or instrument approach procedure, unless ATC assigns a different altitude. The MSA (A) is for emergency use, and the MVA (D) is a controller's tool, not a pilot altitude."}, {"n": 44, "stem": "Which product gives forecast icing probability and severity for planning a flight several hours from now?", "options": ["CIP (Current Icing Product)", "GTG (Graphical Turbulence Guidance)", "A routine PIREP", "FIP (Forecast Icing Product)"], "domain": 2, "answer": 3, "rationale": "The FIP forecasts icing probability, severity, and supercooled large droplet potential for future hours. The CIP (A) is an analysis of current conditions, the GTG (B) covers turbulence, and a PIREP (C) is an observation from one aircraft at one time and place."}, {"n": 45, "stem": "On an IFR flight lasting 1 hour 10 minutes, a pilot spends 25 minutes between cloud layers with a clear horizon, flying by outside visual references. How much may be logged as actual instrument time?", "options": ["1 hour 10 minutes, because the flight was on an IFR flight plan", "None, because no approach was flown in clouds", "1 hour 10 minutes, because the flight was in controlled airspace", "45 minutes, the time the airplane was flown solely by reference to instruments"], "domain": 1, "answer": 3, "rationale": "Under 61.51(g)(1), instrument time may be logged only for the time the pilot operates the aircraft solely by reference to instruments under actual or simulated instrument flight conditions. Being on an IFR flight plan (A) or in controlled airspace (C) does not make time instrument time, and no approach (B) is needed to log it."}, {"n": 46, "stem": "In the circling line of an approach chart's minimums, what is the smaller number printed after the MDA and visibility?", "options": ["HAT, the height above the touchdown zone of the landing runway", "The threshold elevation above mean sea level", "The visibility expressed as RVR in hundreds of feet", "HAA, the height above airport elevation"], "domain": 5, "answer": 3, "rationale": "Circling minimums show height above airport (HAA), the MDA's height above the published airport elevation. Straight-in minimums show HAT (A), measured from the touchdown zone elevation of the runway."}, {"n": 47, "stem": "At night, a pilot stares at a single stationary light against a dark background, and the light seems to move. What is this called?", "options": ["Autokinesis", "False horizon", "Flicker vertigo", "Size-distance illusion"], "domain": 6, "answer": 0, "rationale": "Autokinesis is the apparent movement of a stationary light when it is stared at for many seconds in the dark. A pilot may lose control trying to align with it. The cure is to keep the eyes moving and to cross-check the instruments."}, {"n": 48, "stem": "When flying a DME arc with an RMI or bearing pointer, which technique keeps the airplane on the arc?", "options": ["Keep the bearing pointer on the nose and fly directly toward the station", "Hold a constant heading and correct only after the DME changes by 1 mile", "Keep the bearing pointer near the wingtip reference, turning slightly toward the station as the pointer moves behind the wingtip", "Keep the station directly behind the airplane until the DME stops changing"], "domain": 4, "answer": 2, "rationale": "On an arc, the station stays roughly 90° off the nose, so the bearing pointer stays near the wingtip reference. As the pointer drifts behind the wingtip, a small turn toward the station (about 10° in no wind) keeps the distance constant. Flying toward the station (A) or away from it (D) changes the distance."}, {"n": 49, "stem": "When complying with an ATC speed adjustment, pilots are expected to maintain the assigned speed within", "options": ["±5 knots", "±15 knots", "±10 knots or 0.02 Mach", "±20 knots"], "domain": 3, "answer": 2, "rationale": "The AIM states that pilots complying with speed adjustments are expected to maintain a speed within plus or minus 10 knots or 0.02 Mach number of the specified speed. If a speed cannot be flown safely, the pilot should tell ATC."}, {"n": 50, "stem": "For a flight under IFR, 91.103 requires the pilot in command to become familiar with runway lengths and takeoff and landing distance data. Which other items does it specifically require?", "options": ["Weather reports and forecasts, fuel requirements, alternatives if the flight cannot be completed as planned, and known traffic delays advised by ATC", "Weather reports and forecasts, the date of the last annual inspection, and NOTAMs for the alternate only", "Fuel requirements, each passenger's weight, and the location of the nearest Flight Service Station", "Known traffic delays, the departure ATIS, and the expected IFR clearance"], "domain": 1, "answer": 0, "rationale": "Section 91.103(a) lists weather reports and forecasts, fuel requirements, alternatives available if the planned flight cannot be completed, and any known traffic delays of which the pilot has been advised by ATC, for any flight under IFR or not in the vicinity of an airport. The other choices mix in items the rule does not name."}]}], "decks": [{"name": "Regulations and Equipment", "cards": [{"front": "ACS (Airman Certification Standards)", "back": "The FAA document that defines the knowledge, risk management, and skill standards for a certificate or rating."}, {"front": "Airworthiness directive (AD)", "back": "A legally enforceable rule issued to correct an unsafe condition in an aircraft, engine, propeller, or appliance."}, {"front": "BasicMed", "back": "An alternative to holding an FAA medical certificate, with specific limitations on aircraft and operations."}, {"front": "ELT (emergency locator transmitter)", "back": "A transmitter that activates in a crash to help searchers find the aircraft."}, {"front": "IPC (instrument proficiency check)", "back": "A check required to restore instrument currency after the grace period."}, {"front": "KOEL (kinds of operations equipment list)", "back": "A list in the flight manual showing which equipment is required for each kind of operation."}, {"front": "Letter of Discontinuance", "back": "A document issued when a practical test is stopped for reasons not related to the applicant's performance."}, {"front": "MEL (minimum equipment list)", "back": "An FAA-approved list of equipment that may be inoperative for a specific aircraft, under stated conditions."}, {"front": "Notice of Disapproval", "back": "A document issued when an applicant fails one or more Tasks on a practical test."}, {"front": "Safety pilot", "back": "An appropriately rated pilot who watches for traffic while another pilot flies in simulated instrument conditions."}, {"front": "Special VFR", "back": "A VFR clearance to operate in controlled airspace below basic VFR minimums, with limitations."}, {"front": "ADS-B Out", "back": "Equipment that broadcasts the aircraft's position, altitude, and other data for use by ATC and other aircraft."}, {"front": "Transponder", "back": "Equipment that replies to ATC radar interrogations with a code and, when equipped, altitude."}, {"front": "VOT (VOR test facility)", "back": "A ground transmitter used to check VOR receiver accuracy."}, {"front": "Alternate airport", "back": "An airport listed in the flight plan where an aircraft may land if landing at the intended destination becomes inadvisable."}, {"front": "Alternate minimums", "back": "The forecast ceiling and visibility required to list an airport as an alternate."}]}, {"name": "Weather", "cards": [{"front": "Abbreviated briefing", "back": "A weather briefing that updates earlier information or provides only specific items the pilot requests."}, {"front": "Advection fog", "back": "Fog that forms when moist air moves over a colder surface."}, {"front": "AIRMET", "back": "An advisory of weather that may be hazardous, particularly to lighter aircraft. Issued as Sierra, Tango, and Zulu."}, {"front": "ASOS/AWOS", "back": "Automated surface weather observing systems at airports."}, {"front": "ATIS (Automatic Terminal Information Service)", "back": "A recorded broadcast of current weather and airport information at a towered airport."}, {"front": "Broken (BKN)", "back": "Sky cover of five-eighths to seven-eighths; a broken layer constitutes a ceiling."}, {"front": "Ceiling", "back": "The height above ground of the lowest layer reported as broken or overcast, or the vertical visibility into an obscuration."}, {"front": "Center Weather Advisory (CWA)", "back": "A short-term weather warning issued by meteorologists at an ARTCC, valid for up to two hours."}, {"front": "Clear ice", "back": "Glossy, transparent, heavy structural ice formed by large supercooled droplets that spread before freezing."}, {"front": "Convective SIGMET", "back": "An advisory for thunderstorms and associated hazards, issued hourly and valid for two hours."}, {"front": "Density altitude", "back": "Pressure altitude corrected for nonstandard temperature; determines aircraft performance."}, {"front": "Dew point", "back": "The temperature to which air must be cooled to become saturated."}, {"front": "Freezing rain", "back": "Rain that falls as liquid and freezes on contact with surfaces at temperatures below freezing."}, {"front": "GFA (Graphical Forecasts for Aviation)", "back": "An interactive graphical display of observed and forecast aviation weather for the contiguous United States."}, {"front": "Inversion", "back": "A layer in which temperature increases with altitude."}, {"front": "Isobar", "back": "A line connecting points of equal pressure on a weather chart."}, {"front": "Lapse rate", "back": "The rate at which temperature decreases with altitude."}, {"front": "METAR", "back": "A routine aviation surface weather observation."}, {"front": "Microburst", "back": "An intense, localized downdraft that spreads outward on reaching the ground."}, {"front": "Overcast (OVC)", "back": "Sky cover of eight-eighths; an overcast layer constitutes a ceiling."}, {"front": "PIREP (pilot report)", "back": "A report of weather conditions encountered in flight."}, {"front": "Prognostic chart", "back": "A chart showing forecast positions of weather systems."}, {"front": "Radiation fog", "back": "Fog that forms over land on clear, calm nights as the ground cools the air above it."}, {"front": "Rime ice", "back": "Rough, milky structural ice formed when small supercooled droplets freeze instantly."}, {"front": "Scattered (SCT)", "back": "Sky cover of three-eighths to four-eighths; not a ceiling."}, {"front": "SIGMET", "back": "An advisory of weather potentially hazardous to all aircraft, such as severe icing or severe turbulence."}, {"front": "Standard briefing", "back": "A complete weather briefing for a planned flight."}, {"front": "Supercooled large droplets (SLD)", "back": "Freezing drizzle and freezing rain droplets that may freeze behind protected surfaces."}, {"front": "TAF (Terminal Aerodrome Forecast)", "back": "A forecast for the area within 5 statute miles of an airport's runway complex."}, {"front": "Tailplane stall", "back": "A stall of the horizontal tail, often caused by ice, producing a nose-down pitch."}, {"front": "TEMPO", "back": "A TAF group describing temporary fluctuations lasting less than an hour at a time."}, {"front": "Wind shear", "back": "A change in wind speed or direction over a short distance."}, {"front": "Winds and temperatures aloft forecast", "back": "A forecast of wind direction, speed, and temperature at standard altitudes."}]}, {"name": "Instruments and Systems", "cards": [{"front": "Absolute altitude", "back": "Height above the terrain directly below the aircraft."}, {"front": "ADC (air data computer)", "back": "A computer that processes pitot, static, and temperature inputs to provide airspeed, altitude, vertical speed, and related data to electronic displays."}, {"front": "AHRS (attitude and heading reference system)", "back": "A solid-state system that provides attitude and heading information to electronic flight displays."}, {"front": "Alternate static source", "back": "A valve that supplies static pressure from inside the cabin when the external static port is blocked."}, {"front": "Altimeter setting", "back": "The pressure value set in the altimeter so that it reads field elevation on the ground at the reporting station."}, {"front": "Attitude indicator", "back": "A gyroscopic instrument that shows pitch and bank relative to an artificial horizon."}, {"front": "Calibrated airspeed (CAS)", "back": "Indicated airspeed corrected for instrument and position errors."}, {"front": "Deviation (compass)", "back": "Compass error caused by magnetic fields within the aircraft."}, {"front": "Emphasis (scanning error)", "back": "Relying on one instrument for information that requires several."}, {"front": "Fixation", "back": "A scanning error in which the pilot stares at one instrument and neglects others."}, {"front": "Omission (scanning error)", "back": "Leaving an instrument out of the scan."}, {"front": "Flight level", "back": "An altitude expressed in hundreds of feet with the altimeter set to 29.92, used at and above 18,000 feet MSL in the United States."}, {"front": "Groundspeed", "back": "The speed of the aircraft over the ground."}, {"front": "Heading indicator", "back": "A gyroscopic instrument that shows heading and must be aligned periodically with the magnetic compass."}, {"front": "HSI (horizontal situation indicator)", "back": "An instrument combining a heading indicator and a course deviation indicator."}, {"front": "Indicated airspeed (IAS)", "back": "The airspeed shown on the airspeed indicator."}, {"front": "Magnetic dip", "back": "The downward pull of Earth's magnetic field lines, causing compass turning and acceleration errors."}, {"front": "Maneuvering speed", "back": "The speed at or below which full or abrupt control inputs, or turbulence, will not exceed the aircraft's structural limits; decreases with weight."}, {"front": "Pitot tube", "back": "A probe that senses ram air pressure for the airspeed indicator."}, {"front": "Precession", "back": "The tendency of a gyroscope to react to a force 90 degrees later in its direction of rotation; also causes drift in heading indicators."}, {"front": "Pressure altitude", "back": "The altitude indicated when the altimeter is set to 29.92 inches of mercury."}, {"front": "Rate of turn indicator", "back": "A gyroscopic instrument, such as a turn coordinator, showing how fast the aircraft is turning."}, {"front": "Rigidity in space", "back": "The property of a spinning gyroscope to resist changes in the orientation of its axis."}, {"front": "Standard rate turn", "back": "A turn of 3 degrees per second."}, {"front": "Static port", "back": "An opening that senses ambient air pressure for the pitot-static instruments."}, {"front": "Timed turn", "back": "A turn made at standard rate for a calculated time to achieve a heading change."}, {"front": "True airspeed (TAS)", "back": "Calibrated airspeed corrected for altitude and temperature."}, {"front": "True altitude", "back": "The actual height above mean sea level."}, {"front": "Turn coordinator", "back": "A gyroscopic instrument showing rate of roll and rate of turn."}, {"front": "Unusual attitude", "back": "Any aircraft attitude not normally required for instrument flight."}, {"front": "Variation", "back": "The angular difference between true north and magnetic north."}, {"front": "Vertical speed indicator (VSI)", "back": "An instrument showing rate of climb or descent."}]}, {"name": "Navigation", "cards": [{"front": "ADF (automatic direction finder)", "back": "An aircraft receiver whose needle points toward a nondirectional beacon."}, {"front": "Back course", "back": "The localizer course extending from the opposite end of the runway from the normal front course."}, {"front": "Bracketing", "back": "A technique for finding the wind correction angle by making progressively smaller heading corrections."}, {"front": "Course deviation indicator (CDI)", "back": "The needle or display showing the aircraft's lateral position relative to a selected course."}, {"front": "DME (distance measuring equipment)", "back": "Equipment that measures slant-range distance from the aircraft to a ground station."}, {"front": "DME arc", "back": "A curved flight path at a constant DME distance from a station."}, {"front": "False glide slope", "back": "A spurious glide slope signal at an angle above the true glide path."}, {"front": "Fly-by waypoint", "back": "A waypoint at which the navigator anticipates the turn and begins it before reaching the waypoint."}, {"front": "Fly-over waypoint", "back": "A waypoint that must be crossed before a turn begins."}, {"front": "Glide slope", "back": "The vertical guidance component of an ILS."}, {"front": "GPS (Global Positioning System)", "back": "A satellite navigation system that provides position, velocity, and time."}, {"front": "ILS (instrument landing system)", "back": "A precision approach system providing lateral guidance (localizer) and vertical guidance (glide slope)."}, {"front": "Localizer", "back": "The lateral guidance component of an ILS, also used alone for LOC approaches."}, {"front": "NDB (nondirectional beacon)", "back": "A ground station transmitting a signal used by an ADF."}, {"front": "OBS (omnibearing selector)", "back": "The knob used to select a course on a VOR indicator."}, {"front": "Radial", "back": "A magnetic bearing extending outward from a VOR."}, {"front": "RAIM (receiver autonomous integrity monitoring)", "back": "A method used by non-WAAS GPS receivers to detect satellite faults."}, {"front": "RNAV (area navigation)", "back": "Navigation that allows flight on any desired path within the coverage of navigation aids or satellite systems."}, {"front": "Slant range", "back": "The straight-line distance from an aircraft to a DME station."}, {"front": "VOR (VHF omnidirectional range)", "back": "A ground navigation aid that transmits radials for navigation."}, {"front": "WAAS (Wide Area Augmentation System)", "back": "A system of ground stations and satellites that improves GPS accuracy and integrity for aviation."}]}, {"name": "ATC, Airspace, and En Route", "cards": [{"front": "ARTCC (Air Route Traffic Control Center)", "back": "An ATC facility that controls IFR traffic en route between terminal areas; often called \"Center.\""}, {"front": "Changeover point (COP)", "back": "The point on an airway where the pilot changes navigation reference from one facility to the next."}, {"front": "Clearance limit", "back": "The fix, point, or location to which an aircraft is cleared."}, {"front": "Clearance void time", "back": "The time after which an IFR clearance is canceled if the aircraft has not departed."}, {"front": "Composite flight plan", "back": "A flight plan that includes both VFR and IFR portions."}, {"front": "Controlled airspace", "back": "Airspace in which ATC services are provided to IFR flights: Classes A, B, C, D, and E."}, {"front": "Cruise clearance", "back": "A clearance assigning a block of airspace from the minimum IFR altitude up to a specified altitude, including authorization to approach at the destination."}, {"front": "Descend via", "back": "A clearance to descend at the pilot's discretion while complying with published altitude and speed restrictions on an arrival procedure."}, {"front": "EFC (expect further clearance time)", "back": "The time at which a pilot can expect to receive further clearance beyond a clearance limit or holding fix."}, {"front": "Expected altitude", "back": "An altitude ATC says to expect in a further clearance, used in lost communication procedures."}, {"front": "FDC NOTAM", "back": "A NOTAM containing regulatory information, including amendments to instrument procedures and temporary flight restrictions."}, {"front": "GNSS MEA", "back": "A minimum en route altitude for aircraft using GPS navigation."}, {"front": "MAA (maximum authorized altitude)", "back": "The highest altitude at which an airway segment is usable."}, {"front": "MCA (minimum crossing altitude)", "back": "The lowest altitude at which a fix must be crossed when proceeding toward a higher MEA."}, {"front": "MEA (minimum en route altitude)", "back": "The lowest published altitude between fixes that assures navigation signal coverage and obstacle clearance."}, {"front": "Minimum fuel", "back": "An advisory to ATC that the pilot can accept little or no delay; not an emergency."}, {"front": "MOA (military operations area)", "back": "Airspace established to separate military training from IFR traffic."}, {"front": "MOCA (minimum obstruction clearance altitude)", "back": "An altitude providing obstacle clearance for a segment and navigation coverage within 22 NM of the VOR."}, {"front": "MRA (minimum reception altitude)", "back": "The lowest altitude at which an intersection can be determined."}, {"front": "MVA (minimum vectoring altitude)", "back": "The lowest altitude at which ATC may vector an IFR aircraft in a radar area."}, {"front": "NOTAM (Notice to Air Missions)", "back": "A notice of a change or hazard in the National Airspace System not yet published in charts or other documents."}, {"front": "OROCA (off-route obstruction clearance altitude)", "back": "An altitude on en route charts providing obstacle clearance within a latitude and longitude grid."}, {"front": "Radar contact", "back": "A statement from ATC that the aircraft has been identified on radar."}, {"front": "Restricted area", "back": "Special use airspace in which hazardous activities occur and flight is restricted when active."}, {"front": "STAR (standard terminal arrival)", "back": "A published arrival route connecting the en route structure to the terminal area."}, {"front": "TFR (temporary flight restriction)", "back": "A temporary restriction of flight in a specific area."}, {"front": "TRACON", "back": "A terminal radar approach control facility providing approach and departure control."}, {"front": "Uncontrolled airspace", "back": "Class G airspace, in which ATC does not provide IFR separation."}, {"front": "VFR-on-top", "back": "An IFR clearance allowing flight at VFR altitudes while complying with VFR weather minimums and IFR rules."}, {"front": "Victor airway", "back": "A VOR-based federal airway below 18,000 feet MSL."}]}, {"name": "Departures, Holding, and Approaches", "cards": [{"front": "Approach category", "back": "A grouping of aircraft based on reference landing speed, used to determine approach minimums."}, {"front": "Approach light system (ALS)", "back": "A configuration of lights extending from the runway threshold outward along the approach path."}, {"front": "APV (approach with vertical guidance)", "back": "An approach that provides lateral and vertical guidance but does not meet precision approach standards, such as LPV or LNAV/VNAV."}, {"front": "Circling approach", "back": "Visual maneuvering after an instrument approach to land on a runway not aligned with the final approach course."}, {"front": "Cold temperature airport", "back": "An airport where pilots must apply altitude corrections when the reported temperature is at or below a published value."}, {"front": "Contact approach", "back": "A pilot-requested approach in which the pilot proceeds to the airport by visual reference to the surface, with at least 1 mile of flight visibility and clear of clouds."}, {"front": "Continuous descent final approach (CDFA)", "back": "A technique for flying a nonprecision final approach at a constant descent angle from the FAF toward the MDA."}, {"front": "Course reversal", "back": "A maneuver, such as a procedure turn or holding pattern in lieu of a procedure turn, used to reverse direction onto the final approach course."}, {"front": "DA (decision altitude)", "back": "The altitude on an approach with vertical guidance at which a missed approach must be started if the required visual references are not established."}, {"front": "Departure end of runway (DER)", "back": "The end of the runway opposite the takeoff threshold, used as the reference for departure procedure design."}, {"front": "Direct entry", "back": "A holding pattern entry in which the pilot crosses the fix and turns in the direction of holding."}, {"front": "Established", "back": "Stable on a published segment of an approach or route."}, {"front": "FAF (final approach fix)", "back": "The fix from which the final approach segment begins."}, {"front": "Feeder route", "back": "A charted route from the en route structure to an initial approach fix."}, {"front": "HAT (height above touchdown)", "back": "The height of a DA or MDA above the touchdown zone elevation."}, {"front": "Holding fix", "back": "The reference point for a holding pattern."}, {"front": "Holding in lieu of procedure turn", "back": "A holding pattern used as the course reversal on an approach."}, {"front": "Holding side", "back": "The side of the inbound course on which the holding pattern is flown."}, {"front": "IAF (initial approach fix)", "back": "The fix where an instrument approach begins."}, {"front": "IF (intermediate fix)", "back": "The fix that begins the intermediate segment of an approach."}, {"front": "LNAV", "back": "An RNAV approach line of minimums with lateral guidance only, using an MDA."}, {"front": "LNAV/VNAV", "back": "An RNAV approach line of minimums with lateral and vertical guidance, using a DA."}, {"front": "LP", "back": "An RNAV approach line of minimums with WAAS lateral guidance similar to a localizer, without vertical guidance."}, {"front": "LPV", "back": "An RNAV approach line of minimums using WAAS lateral and vertical guidance, with a DA that can approach ILS values."}, {"front": "MAP (missed approach point)", "back": "The point on a nonprecision approach at which a missed approach must begin if the required references are not established."}, {"front": "MDA (minimum descent altitude)", "back": "The lowest altitude to which descent is authorized on a nonprecision approach until the required visual references are established."}, {"front": "Missed approach", "back": "The procedure flown when an approach cannot be completed to a landing."}, {"front": "MSA (minimum safe altitude)", "back": "An altitude providing 1,000 feet of obstacle clearance within a stated radius of a facility, for emergency use."}, {"front": "Nonprecision approach", "back": "An approach with lateral guidance only, using an MDA."}, {"front": "NoPT", "back": "A notation on an approach route meaning no procedure turn is required or authorized without ATC clearance."}, {"front": "ODP (obstacle departure procedure)", "back": "A departure procedure designed to provide obstacle clearance from the runway to the en route structure."}, {"front": "PAPI (precision approach path indicator)", "back": "A visual glide slope indicator using a row of lights that appear red or white depending on the approach angle."}, {"front": "Parallel entry", "back": "A holding entry in which the pilot crosses the fix, flies parallel to the inbound course on the non-holding side, then turns back to the fix or inbound course."}, {"front": "Precision approach", "back": "An approach with lateral and vertical guidance meeting precision standards, such as an ILS."}, {"front": "Procedure turn", "back": "A course reversal maneuver flown on the maneuvering side within a specified distance."}, {"front": "REIL (runway end identifier lights)", "back": "Synchronized flashing lights at each side of the runway threshold."}, {"front": "RVR (runway visual range)", "back": "An instrument-measured value of how far a pilot should be able to see down the runway."}, {"front": "SID (standard instrument departure)", "back": "A published ATC departure procedure, assigned by ATC, that also provides obstacle clearance."}, {"front": "Sidestep maneuver", "back": "A visual maneuver from an approach to one runway to land on a parallel runway 1,200 feet or less away."}, {"front": "Stabilized approach", "back": "An approach flown on the correct path, at the correct speed and configuration, with only small corrections required."}, {"front": "Stepdown fix", "back": "A fix on an approach after which descent to a lower altitude is permitted."}, {"front": "TAA (terminal arrival area)", "back": "Areas around an RNAV approach with published altitudes for transitioning to the IAFs."}, {"front": "TDZE (touchdown zone elevation)", "back": "The highest elevation in the first 3,000 feet of the landing surface."}, {"front": "Teardrop entry", "back": "A holding entry in which the pilot crosses the fix, flies outbound on the holding side at an angle of about 30 degrees, then turns to intercept the inbound course."}, {"front": "VDP (visual descent point)", "back": "A defined point on a nonprecision approach from which a normal descent from the MDA to the runway may begin with the required references in sight."}, {"front": "Vectors-to-final", "back": "A GPS function that activates the final approach course for interception during radar vectors."}, {"front": "Visual approach", "back": "An ATC authorization for an IFR aircraft to proceed visually to the airport with the airport or preceding aircraft in sight."}]}, {"name": "Human Factors and Decision-Making", "cards": [{"front": "ADM (aeronautical decision-making)", "back": "A systematic approach to the mental process pilots use to determine the best course of action in a given set of circumstances."}, {"front": "Coriolis illusion", "back": "A strong false sensation of rotation caused by abrupt head movement during a prolonged turn."}, {"front": "Elevator illusion", "back": "A false sensation of climbing or descending caused by an abrupt vertical acceleration."}, {"front": "FRAT (flight risk assessment tool)", "back": "A checklist that assigns scores to risk factors before a flight."}, {"front": "Graveyard spiral", "back": "A descending spiral that results when a pilot, unaware of a prolonged turn, pulls back on the controls to stop an altitude loss."}, {"front": "Hypemic hypoxia", "back": "Hypoxia caused by the blood's reduced ability to carry oxygen, such as from carbon monoxide."}, {"front": "Hyperventilation", "back": "Excessive breathing that lowers the carbon dioxide level in the blood."}, {"front": "Hypoxia", "back": "A deficiency of oxygen in the body sufficient to impair functions."}, {"front": "Hypoxic hypoxia", "back": "Hypoxia caused by insufficient oxygen available to the lungs, such as at altitude."}, {"front": "IMSAFE", "back": "A personal checklist: illness, medication, stress, alcohol, fatigue, emotion or eating."}, {"front": "Leans", "back": "A false sensation of bank after a slow, undetected roll followed by an abrupt correction."}, {"front": "PAVE", "back": "A risk checklist: pilot, aircraft, environment, external pressures."}, {"front": "Somatogravic illusion", "back": "A false sensation of nose-up pitch caused by forward acceleration."}, {"front": "SRM (single-pilot resource management)", "back": "Managing all available resources to ensure a safe flight as a single pilot."}]}]};
